B.am=s([],t.zr)
B.X4=s(["Th..Thank you, Mateo. I..I owe you my life...","The words grow distant as exhaustion pulls you back into darkness."],t.s)
B.Or=new A.cv("Close your eyes","intro_pass_out_to_spanish_home",!0,!1)
B.YQ=s([B.Or],t.u)
