B.X9=s([B.Pe],t.J)
B.OA=new A.cN("Player",B.X9)
B.XB=s(["Then what should I call you?"],t.s)
B.Om=new A.cv("Choose your name","intro_choose_player_name",!0,!1)
B.V0=s([B.Om],t.u)
B.P9=new A.ch(B.am,B.XB,null,null,null,B.V0)
B.Uu=s([B.P9],t.J)
B.OB=new A.cN("Concerned Stranger",B.Uu)
B.Vp=s(["Welcome, captain. Your ship has good bones, but there is always room for finer work.","Would you like to order work on your ship?"],t.s)
B.Oj=new A.cv("View ship upgrades","open_ship_upgrade_menu",!1,!0)
B.XF=s([B.Oj,B.fY],t.u)
B.P_=new A.ch(B.am,B.Vp,null,null,null,B.XF)
B.Xp=s([B.P_],t.J)
B.OC=new A.cN("Shipwright",B.Xp)
B.Wo=s(["The player stirs, violently coughing up seawater. There is a distinct taste of iron admist the saltiness. The chill on your flesh is contrasted by the burning in your side."],t.s)
B.Ok=new A.cv("Next","intro_show_stranger",!0,!1)
B.Z3=s([B.Ok],t.u)
B.P2=new A.ch(B.am,B.Wo,null,null,null,B.Z3)
B.Wg=s([B.P2],t.J)
B.OD=new A.cN("Narrator",B.Wg)
B.WO=s(["I...I...I don't know... I..."],t.s)
B.Of=new A.cv("Try to Remember","intro_show_british_officer",!0,!1)
B.Zb=s([B.Of],t.u)
B.P5=new A.ch(B.am,B.WO,null,null,null,B.Zb)
B.VD=s([B.P5],t.J)
B.OE=new A.cN("Player",B.VD)
B.Yz=s(["I... I cannot remember."],t.s)
B.Og=new A.cv("Continue","intro_ask_player_name",!0,!1)
B.Ww=s([B.Og],t.u)
B.Po=new A.ch(B.am,B.Yz,null,null,null,B.Ww)
B.VU=s([B.Po],t.J)
B.OF=new A.cN("Player",B.VU)
B.Zg=s(["Nothing... apart from a face.","A young man with dark hair and cold eyes. He wore a naval coat finer than any officer's, with a golden lion at his collar.","He looked at me as though he knew me. Then everything went dark."],t.s)
B.O5=new A.cv("Watch Mateo's reaction","intro_mateo_recognizes_prince",!0,!1)
B.YV=s([B.O5],t.u)
B.P7=new A.ch(B.am,B.Zg,null,null,null,B.YV)
B.Yn=s([B.P7],t.J)
B.OG=new A.cN("Player",B.Yn)
B.VA=s(["That sounds like the Prince of Britain.","The British Navy has been cracking down hard on piracy. If you crossed paths with the prince himself, they may have taken you for a pirate.","But the crown calls everyone a criminal when it suits them. The government is corrupt, and poverty has spread across the nation while the powerful line their own pockets.","Many people down on their luck have turned to piracy simply to make ends meet. For some, it is the only way left to put food on the table."],t.s)
B.dP=s([],t.u)
B.Pl=new A.ch(B.am,B.VA,null,null,null,B.dP)
B.V2=s([B.Pl],t.J)
B.OH=new A.cN("Mateo",B.V2)
B.Yv=s(["Welcome to the cafe, captain. You look like you could use something strong after your voyage.","Would you like to browse today's menu of consumables?"],t.s)
B.O8=new A.cv("Browse menu","open_spanish_cafe_menu",!0,!1)
B.V1=s([B.O8,B.fY],t.u)
B.Pd=new A.ch(B.am,B.Yv,null,null,null,B.V1)
B.YW=s([B.Pd],t.J)
B.OI=new A.cN("Barista",B.YW)
B.YN=s(["Hey\u2014stay with me. Can you hear me?","Who are you?"],t.s)
B.O4=new A.cv("Try to remember","intro_cannot_remember_name",!0,!1)
B.Xc=s([B.O4],t.u)
B.P4=new A.ch(B.am,B.YN,null,null,null,B.Xc)
B.YF=s([B.P4],t.J)
B.OJ=new A.cN("Concerned Stranger",B.YF)
B.YX=s(["The fortress harbor opens, and the Royal Navy sails out to meet you.","Gilded warships spread across the channel beneath British flags, forming a wall between your fleet and the island.","Neither armada turns away."],t.s)
B.Pg=new A.ch(B.am,B.YX,null,null,null,B.dP)
B.YP=s([B.Pg],t.J)
B.OK=new A.cN("Narrator",B.YP)
B.Wu=s(["The cave trembles as something immense stirs beneath the black water.","A forest of tentacles rises from the depths, and a furious eye fixes upon your crew.","You were a fool to come here."],t.s)
B.Oq=new A.cv("Face the Kraken","start_kraken_fight",!0,!1)
B.Wr=s([B.Oq],t.u)
B.Pp=new A.ch(B.am,B.Wu,null,null,null,B.Wr)
B.Wx=s([B.Pp],t.J)
B.OL=new A.cN("The Kraken",B.Wx)
B.Wz=s(["You close your eyes. The room falls away.","His face emerges from the darkness, framed by drifting smoke: the same cold stare, the same golden insignia."],t.s)
B.Op=new A.cv("Open your eyes","intro_describe_remembered_face",!0,!1)
B.W9=s([B.Op],t.u)
B.Pc=new A.ch(B.am,B.Wz,null,null,null,B.W9)
B.Uk=s([B.Pc],t.J)
B.OM=new A.cN("Narrator",B.Uk)
B.V9=s(["Thank god... I feared the worst. What happened to you?"],t.s)
