B.Yk=s([B.Pf],t.J)
B.ON=new A.cN("Stranger",B.Yk)
B.YY=s(["I was on my way to the docks when I found you. I was sure you were dead...","The doctor has been by to check on you. Your body, he says, will heal, but he cannot explain your memory loss.","Now that you are awake, do you remember anything about what happened to you?"],t.s)
B.Oi=new A.cv("Try to remember","intro_recall_prince_face",!0,!1)
B.Z_=s([B.Oi],t.u)
B.P8=new A.ch(B.am,B.YY,null,null,null,B.Z_)
B.Zc=s([B.P8],t.J)
B.OO=new A.cN("Mateo",B.Zc)
B.Wy=s(["Welcome aboard, sailor. I am Captain Lorenzo, and I assign bounties to crews bold enough to earn them.","A bounty is a promise: I name the target, you bring back proof, and the reward is yours.","I have a first contract waiting. Will you accept it?"],t.s)
B.On=new A.cv("Accept first bounty","accept_italy_first_bounty",!0,!0)
B.Od=new A.cv("Not yet","close_dialogue",!0,!0)
B.XM=s([B.On,B.Od],t.u)
B.OZ=new A.ch(B.am,B.Wy,null,null,"italy_first_bounty",B.XM)
B.YH=s(["Redfin is defeated. You have done Italy a service, captain.","As promised, your bounty is 500 gold."],t.s)
B.hD=new A.wq(1,"readyToTurnIn")
B.Oa=new A.cv("Claim bounty","claim_italy_first_bounty",!0,!0)
B.YT=s([B.Oa],t.u)
B.P0=new A.ch(B.am,B.YH,"italy_first_bounty",B.hD,null,B.YT)
B.Xu=s(["Redfin will trouble these waters no more. Spend your reward wisely, captain.","Another Redfin has been sighted. Will you take the next contract?"],t.s)
B.jR=new A.wq(2,"completed")
B.Ol=new A.cv("Accept another bounty","accept_italy_first_bounty",!0,!0)
B.X1=s([B.Ol,B.fY],t.u)
B.P3=new A.ch(B.am,B.Xu,"italy_first_bounty",B.jR,null,B.X1)
B.Un=s(["Your target is Redfin, a vicious crimson beast seen in open waters.","It is rarely sighted. Keep fighting at sea and watch for its red scales."],t.s)
B.dm=new A.wq(0,"active")
B.Pb=new A.ch(B.am,B.Un,"italy_first_bounty",B.dm,null,B.dP)
